import { Component, For, onCleanup, Show } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useAspectRatio, useIsSmallScreen, useWindowSize } from "#core/ui-next/utilities/layout-utilities.js";

import { AdvisorCard } from "#base/ui-next/screens/advisor-council/advisor-card.jsx";
import { useAdvisorScreenContext } from "#base/ui-next/screens/advisor-council/advisor-screen-model.js";

export interface CouncilRoomProps {
	isPopup: boolean;
}

export const CouncilRoom: Component<CouncilRoomProps> = (props) => {
	const model = useAdvisorScreenContext();

	const windowHeight = useWindowSize();
	const isSmallScreen = useIsSmallScreen();
	const aspectRatio = useAspectRatio();
	const isMobile = ViewExperience() == UIViewExperience.Mobile;

	onCleanup(() => {
		model.setSelectedAdvisorCard(AdvisorTypes.NO_ADVISOR);
	});

	return (
		<div class="w-full h-full flex flex-col items-center">
			<Show when={!isSmallScreen() || aspectRatio() <= 1.335}>
				<div
					class={`advisor-header-intro text-center text-accent-2 text-sm ${aspectRatio() <= 1.335 && windowHeight() >= 1080 ? "mt-10 mb-12" : "my-3"}`}
					role="heading"
				>
					<L10n.Compose text={"LOC_ADVISOR_COUNCIL_SCREEN_DESCRIPTION"} />
				</div>
			</Show>
			<VSlot class="flex-1 w-full ">
				<div
					class={`${isSmallScreen() ? (aspectRatio() <= 1.335 || isMobile ? "mt-7 mx-8" : "mt-10 mx-8") : aspectRatio() <= 1.335 ? "mt-14 mx-14" : "mt-32 mx-14"} ${isMobile && isSmallScreen() && IsControllerActive() ? "pb-2" : ""}`}
				>
					<HSlot class="flex flex-row w-full h-full justify-center">
						<For each={model.advisorsData}>
							{(advisorsData) => (
								<AdvisorCard
									type={advisorsData.type}
									title={advisorsData.title}
									isInitialPopup={props.isPopup}
									activatable
								/>
							)}
						</For>
					</HSlot>
				</div>
				<Activatable
					hotkeyAction={"shell-action-2"}
					navTrayText={
						model.isFollowing(model.getSelectedAdvisorCard())
							? "LOC_UI_ADVISORS_UNFOLLOW"
							: "LOC_UI_ADVISORS_FOLLOW"
					}
					disableFocus
					onActivate={() => {
						if (IsControllerActive()) {
							model.playFollowAudio(model.getSelectedAdvisorCard());
						}

						if (model.isFollowing(model.getSelectedAdvisorCard())) {
							model.unfollow(model.getSelectedAdvisorCard());
						} else {
							model.follow(model.getSelectedAdvisorCard());
						}
					}}
				/>
				{/* Stand-in navTray text for the 4 Advisor Cards that can be activated. */}
				<Show when={IsControllerActive()}>
					<Activatable
						hotkeyAction={"accept"}
						navTrayText={props.isPopup ? "LOC_ADVISOR_COUNCIL_CONFIRM" : "LOC_UI_ADVISORS_VIEW_PAGE"}
						disableFocus
					/>
				</Show>
			</VSlot>
		</div>
	);
};
